(5596, 76, 5, 'إِنَّ الْأَبْرَارَ يَشْرَبُونَ مِن كَأْسٍ كَانَ مِزَاجُهَا كَافُورًا', 'الانسان', 578, 29, 116),
(5597, 76, 6, 'عَيْنًا يَشْرَبُ بِهَا عِبَادُ اللَّهِ يُفَجِّرُونَهَا تَفْجِيرًا', 'الانسان', 579, 29, 116),
(5598, 76, 7, 'يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا', 'الانسان', 579, 29, 116),
(5599, 76, 8, 'وَيُطْعِمُونَ الطَّعَامَ عَلَىٰ حُبِّهِ مِسْكِينًا وَيَتِيمًا وَأَسِيرًا', 'الانسان', 579, 29, 116),
(5600, 76, 9, 'إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ اللَّهِ لَا نُرِيدُ مِنكُمْ جَزَاءً وَلَا شُكُورًا', 'الانسان', 579, 29, 116),
(5601, 76, 10, 'إِنَّا نَخَافُ مِن رَّبِّنَا يَوْمًا عَبُوسًا قَمْطَرِيرًا', 'الانسان', 579, 29, 116),
(5602, 76, 11, 'فَوَقَاهُمُ اللَّهُ شَرَّ ذَٰلِكَ الْيَوْمِ وَلَقَّاهُمْ نَضْرَةً وَسُرُورًا', 'الانسان', 579, 29, 116),
(5603, 76, 12, 'وَجَزَاهُم بِمَا صَبَرُوا جَنَّةً وَحَرِيرًا', 'الانسان', 579, 29, 116),
(5604, 76, 13, 'مُّتَّكِئِينَ فِيهَا عَلَى الْأَرَائِكِ ۖ لَا يَرَوْنَ فِيهَا شَمْسًا وَلَا زَمْهَرِيرًا', 'الانسان', 579, 29, 116),
(5605, 76, 14, 'وَدَانِيَةً عَلَيْهِمْ ظِلَالُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلًا', 'الانسان', 579, 29, 116),
(5606, 76, 15, 'وَيُطَافُ عَلَيْهِم بِآنِيَةٍ مِّن فِضَّةٍ وَأَكْوَابٍ كَانَتْ قَوَارِيرَا', 'الانسان', 579, 29, 116),
(5607, 76, 16, 'قَوَارِيرَ مِن فِضَّةٍ قَدَّرُوهَا تَقْدِيرًا', 'الانسان', 579, 29, 116),
(5608, 76, 17, 'وَيُسْقَوْنَ فِيهَا كَأْسًا كَانَ مِزَاجُهَا زَنجَبِيلًا', 'الانسان', 579, 29, 116),
(5609, 76, 18, 'عَيْنًا فِيهَا تُسَمَّىٰ سَلْسَبِيلًا', 'الانسان', 579, 29, 116),
(5610, 76, 19, 'وَيَطُوفُ عَلَيْهِمْ وِلْدَانٌ مُّخَلَّدُونَ إِذَا رَأَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤًا مَّنثُورًا', 'الانسان', 579, 29, 116),
(5611, 76, 20, 'وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيمًا وَمُلْكًا كَبِيرًا', 'الانسان', 579, 29, 116),
(5612, 76, 21, 'عَالِيَهُمْ ثِيَابُ سُندُسٍ خُضْرٌ وَإِسْتَبْرَقٌ ۖ وَحُلُّوا أَسَاوِرَ مِن فِضَّةٍ وَسَقَاهُمْ رَبُّهُمْ شَرَابًا طَهُورًا', 'الانسان', 579, 29, 116),
(5613, 76, 22, 'إِنَّ هَـٰذَا كَانَ لَكُمْ جَزَاءً وَكَانَ سَعْيُكُم مَّشْكُورًا', 'الانسان', 579, 29, 116),
(5614, 76, 23, 'إِنَّا نَحْنُ نَزَّلْنَا عَلَيْكَ الْقُرْآنَ تَنزِيلًا', 'الانسان', 579, 29, 116),
(5615, 76, 24, 'فَاصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تُطِعْ مِنْهُمْ آثِمًا أَوْ كَفُورًا', 'الانسان', 579, 29, 116),
(5616, 76, 25, 'وَاذْكُرِ اسْمَ رَبِّكَ بُكْرَةً وَأَصِيلًا', 'الانسان', 579, 29, 116),
(5617, 76, 26, 'وَمِنَ اللَّيْلِ فَاسْجُدْ لَهُ وَسَبِّحْهُ لَيْلًا طَوِيلًا', 'الانسان', 580, 29, 116),
(5618, 76, 27, 'إِنَّ هَـٰؤُلَاءِ يُحِبُّونَ الْعَاجِلَةَ وَيَذَرُونَ وَرَاءَهُمْ يَوْمًا ثَقِيلًا', 'الانسان', 580, 29, 116),
(5619, 76, 28, 'نَّحْنُ خَلَقْنَاهُمْ وَشَدَدْنَا أَسْرَهُمْ ۖ وَإِذَا شِئْنَا بَدَّلْنَا أَمْثَالَهُمْ تَبْدِيلًا', 'الانسان', 580, 29, 116),
(5620, 76, 29, 'إِنَّ هَـٰذِهِ تَذْكِرَةٌ ۖ فَمَن شَاءَ اتَّخَذَ إِلَىٰ رَبِّهِ سَبِيلًا', 'الانسان', 580, 29, 116),
(5621, 76, 30, 'وَمَا تَشَاءُونَ إِلَّا أَن يَشَاءَ اللَّهُ ۚ إِنَّ اللَّهَ كَانَ عَلِيمًا حَكِيمًا', 'الانسان', 580, 29, 116),
(5622, 76, 31, 'يُدْخِلُ مَن يَشَاءُ فِي رَحْمَتِهِ ۚ وَالظَّالِمِينَ أَعَدَّ لَهُمْ عَذَابًا أَلِيمًا', 'الانسان', 580, 29, 116),
(5623, 77, 1, 'بِسْمِ اللَّهِ الرَّحْمَـٰنِ الرَّحِيمِ وَالْمُرْسَلَاتِ عُرْفًا', 'المرسلات', 580, 29, 116),
(5624, 77, 2, 'فَالْعَاصِفَاتِ عَصْفًا', 'المرسلات', 580, 29, 116),
(5625, 77, 3, 'وَالنَّاشِرَاتِ نَشْرًا', 'المرسلات', 580, 29, 116),
(5626, 77, 4, 'فَالْفَارِقَاتِ فَرْقًا', 'المرسلات', 580, 29, 116),
(5627, 77, 5, 'فَالْمُلْقِيَاتِ ذِكْرًا', 'المرسلات', 580, 29, 116),
(5628, 77, 6, 'عُذْرًا أَوْ نُذْرًا', 'المرسلات', 580, 29, 116);
INSERT INTO `quran_text` (`index`, `sura`, `aya`, `text`, `sura_name`, `page`, `juz`, `hezb`) VALUES
(5629, 77, 7, 'إِنَّمَا تُوعَدُونَ لَوَاقِعٌ', 'المرسلات', 580, 29, 116),
(5630, 77, 8, 'فَإِذَا النُّجُومُ طُمِسَتْ', 'المرسلات', 580, 29, 116),
(5631, 77, 9, 'وَإِذَا السَّمَاءُ فُرِجَتْ', 'المرسلات', 580, 29, 116),
(5632, 77, 10, 'وَإِذَا الْجِبَالُ نُسِفَتْ', 'المرسلات', 580, 29, 116),
(5633, 77, 11, 'وَإِذَا الرُّسُلُ أُقِّتَتْ', 'المرسلات', 580, 29, 116),
(5634, 77, 12, 'لِأَيِّ يَوْمٍ أُجِّلَتْ', 'المرسلات', 580, 29, 116),
(5635, 77, 13, 'لِيَوْمِ الْفَصْلِ', 'المرسلات', 580, 29, 116),
(5636, 77, 14, 'وَمَا أَدْرَاكَ مَا يَوْمُ الْفَصْلِ', 'المرسلات', 580, 29, 116),
(5637, 77, 15, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'المرسلات', 580, 29, 116),
(5638, 77, 16, 'أَلَمْ نُهْلِكِ الْأَوَّلِينَ', 'المرسلات', 580, 29, 116),
(5639, 77, 17, 'ثُمَّ نُتْبِعُهُمُ الْآخِرِينَ', 'المرسلات', 580, 29, 116),
(5640, 77, 18, 'كَذَٰلِكَ نَفْعَلُ بِالْمُجْرِمِينَ', 'المرسلات', 580, 29, 116),
(5641, 77, 19, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'المرسلات', 580, 29, 116),
(5642, 77, 20, 'أَلَمْ نَخْلُقكُّم مِّن مَّاءٍ مَّهِينٍ', 'المرسلات', 581, 29, 116),
(5643, 77, 21, 'فَجَعَلْنَاهُ فِي قَرَارٍ مَّكِينٍ', 'المرسلات', 581, 29, 116),
(5644, 77, 22, 'إِلَىٰ قَدَرٍ مَّعْلُومٍ', 'المرسلات', 581, 29, 116),
(5645, 77, 23, 'فَقَدَرْنَا فَنِعْمَ الْقَادِرُونَ', 'المرسلات', 581, 29, 116),
(5646, 77, 24, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'المرسلات', 581, 29, 116),
(5647, 77, 25, 'أَلَمْ نَجْعَلِ الْأَرْضَ كِفَاتًا', 'المرسلات', 581, 29, 116),
(5648, 77, 26, 'أَحْيَاءً وَأَمْوَاتًا', 'المرسلات', 581, 29, 116),
(5649, 77, 27, 'وَجَعَلْنَا فِيهَا رَوَاسِيَ شَامِخَاتٍ وَأَسْقَيْنَاكُم مَّاءً فُرَاتًا', 'المرسلات', 581, 29, 116),
(5650, 77, 28, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'المرسلات', 581, 29, 116),
(5651, 77, 29, 'انطَلِقُوا إِلَىٰ مَا كُنتُم بِهِ تُكَذِّبُونَ', 'المرسلات', 581, 29, 116),
(5652, 77, 30, 'انطَلِقُوا إِلَىٰ ظِلٍّ ذِي ثَلَاثِ شُعَبٍ', 'المرسلات', 581, 29, 116),
(5653, 77, 31, 'لَّا ظَلِيلٍ وَلَا يُغْنِي مِنَ اللَّهَبِ', 'المرسلات', 581, 29, 116),
(5654, 77, 32, 'إِنَّهَا تَرْمِي بِشَرَرٍ كَالْقَصْرِ', 'المرسلات', 581, 29, 116),
(5655, 77, 33, 'كَأَنَّهُ جِمَالَتٌ صُفْرٌ', 'المرسلات', 581, 29, 116),
(5656, 77, 34, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'المرسلات', 581, 29, 116),
(5657, 77, 35, 'هَـٰذَا يَوْمُ لَا يَنطِقُونَ', 'المرسلات', 581, 29, 116),
(5658, 77, 36, 'وَلَا يُؤْذَنُ لَهُمْ فَيَعْتَذِرُونَ', 'المرسلات', 581, 29, 116),
(5659, 77, 37, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'المرسلات', 581, 29, 116),
(5660, 77, 38, 'هَـٰذَا يَوْمُ الْفَصْلِ ۖ جَمَعْنَاكُمْ وَالْأَوَّلِينَ', 'المرسلات', 581, 29, 116),
(5661, 77, 39, 'فَإِن كَانَ لَكُمْ كَيْدٌ فَكِيدُونِ', 'المرسلات', 581, 29, 116),
(5662, 77, 40, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'المرسلات', 581, 29, 116),
(5663, 77, 41, 'إِنَّ الْمُتَّقِينَ فِي ظِلَالٍ وَعُيُونٍ', 'المرسلات', 581, 29, 116),
(5664, 77, 42, 'وَفَوَاكِهَ مِمَّا يَشْتَهُونَ', 'المرسلات', 581, 29, 116),
(5665, 77, 43, 'كُلُوا وَاشْرَبُوا هَنِيئًا بِمَا كُنتُمْ تَعْمَلُونَ', 'المرسلات', 581, 29, 116),
(5666, 77, 44, 'إِنَّا كَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ', 'المرسلات', 581, 29, 116),
(5667, 77, 45, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'المرسلات', 581, 29, 116),
(5668, 77, 46, 'كُلُوا وَتَمَتَّعُوا قَلِيلًا إِنَّكُم مُّجْرِمُونَ', 'المرسلات', 581, 29, 116),
(5669, 77, 47, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'المرسلات', 581, 29, 116),
(5670, 77, 48, 'وَإِذَا قِيلَ لَهُمُ ارْكَعُوا لَا يَرْكَعُونَ', 'المرسلات', 581, 29, 116),
(5671, 77, 49, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 'المرسلات', 581, 29, 116),
(5672, 77, 50, 'فَبِأَيِّ حَدِيثٍ بَعْدَهُ يُؤْمِنُونَ', 'المرسلات', 581, 29, 116),
(5673, 78, 1, 'بِسْمِ اللَّهِ الرَّحْمَـٰنِ الرَّحِيمِ عَمَّ يَتَسَاءَلُونَ', 'النبأ', 582, 30, 117),
(5674, 78, 2, 'عَنِ النَّبَإِ الْعَظِيمِ', 'النبأ', 582, 30, 117),
(5675, 78, 3, 'الَّذِي هُمْ فِيهِ مُخْتَلِفُونَ', 'النبأ', 582, 30, 117),
(5676, 78, 4, 'كَلَّا سَيَعْلَمُونَ', 'النبأ', 582, 30, 117),
(5677, 78, 5, 'ثُمَّ كَلَّا سَيَعْلَمُونَ', 'النبأ', 582, 30, 117),
(5678, 78, 6, 'أَلَمْ نَجْعَلِ الْأَرْضَ مِهَادًا', 'النبأ', 582, 30, 117),
(5679, 78, 7, 'وَالْجِبَالَ أَوْتَادًا', 'النبأ', 582, 30, 117),
(5680, 78, 8, 'وَخَلَقْنَاكُمْ أَزْوَاجًا', 'النبأ', 582, 30, 117),
(5681, 78, 9, 'وَجَعَلْنَا نَوْمَكُمْ سُبَاتًا', 'النبأ', 582, 30, 117),
(5682, 78, 10, 'وَجَعَلْنَا اللَّيْلَ لِبَاسًا', 'النبأ', 582, 30, 117),
(5683, 78, 11, 'وَجَعَلْنَا النَّهَارَ مَعَاشًا', 'النبأ', 582, 30, 117),
(5684, 78, 12, 'وَبَنَيْنَا فَوْقَكُمْ سَبْعًا شِدَادًا', 'النبأ', 582, 30, 117),
(5685, 78, 13, 'وَجَعَلْنَا سِرَاجًا وَهَّاجًا', 'النبأ', 582, 30, 117),
(5686, 78, 14, 'وَأَنزَلْنَا مِنَ الْمُعْصِرَاتِ مَاءً ثَجَّاجًا', 'النبأ', 582, 30, 117),
(5687, 78, 15, 'لِّنُخْرِجَ بِهِ حَبًّا وَنَبَاتًا', 'النبأ', 582, 30, 117),
(5688, 78, 16, 'وَجَنَّاتٍ أَلْفَافًا', 'النبأ', 582, 30, 117),
(5689, 78, 17, 'إِنَّ يَوْمَ الْفَصْلِ كَانَ مِيقَاتًا', 'النبأ', 582, 30, 117),
(5690, 78, 18, 'يَوْمَ يُنفَخُ فِي الصُّورِ فَتَأْتُونَ أَفْوَاجًا', 'النبأ', 582, 30, 117),
(5691, 78, 19, 'وَفُتِحَتِ السَّمَاءُ فَكَانَتْ أَبْوَابًا', 'النبأ', 582, 30, 117),
(5692, 78, 20, 'وَسُيِّرَتِ الْجِبَالُ فَكَانَتْ سَرَابًا', 'النبأ', 582, 30, 117),
(5693, 78, 21, 'إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا', 'النبأ', 582, 30, 117),
(5694, 78, 22, 'لِّلطَّاغِينَ مَآبًا', 'النبأ', 582, 30, 117),
(5695, 78, 23, 'لَّابِثِينَ فِيهَا أَحْقَابًا', 'النبأ', 582, 30, 117),
(5696, 78, 24, 'لَّا يَذُوقُونَ فِيهَا بَرْدًا وَلَا شَرَابًا', 'النبأ', 582, 30, 117),
(5697, 78, 25, 'إِلَّا حَمِيمًا وَغَسَّاقًا', 'النبأ', 582, 30, 117),
(5698, 78, 26, 'جَزَاءً وِفَاقًا', 'النبأ', 582, 30, 117),
(5699, 78, 27, 'إِنَّهُمْ كَانُوا لَا يَرْجُونَ حِسَابًا', 'النبأ', 582, 30, 117),
(5700, 78, 28, 'وَكَذَّبُوا بِآيَاتِنَا كِذَّابًا', 'النبأ', 582, 30, 117),
(5701, 78, 29, 'وَكُلَّ شَيْءٍ أَحْصَيْنَاهُ كِتَابًا', 'النبأ', 582, 30, 117),
(5702, 78, 30, 'فَذُوقُوا فَلَن نَّزِيدَكُمْ إِلَّا عَذَابًا', 'النبأ', 582, 30, 117),
(5703, 78, 31, 'إِنَّ لِلْمُتَّقِينَ مَفَازًا', 'النبأ', 583, 30, 117),
(5704, 78, 32, 'حَدَائِقَ وَأَعْنَابًا', 'النبأ', 583, 30, 117),
