(3896, 37, 108, 'وَتَرَكْنَا عَلَيْهِ فِي الْآخِرِينَ', 0),
(3897, 37, 109, 'سَلَامٌ عَلَىٰ إِبْرَاهِيمَ', 0),
(3898, 37, 110, 'كَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ', 0),
(3899, 37, 111, 'إِنَّهُ مِنْ عِبَادِنَا الْمُؤْمِنِينَ', 0),
(3900, 37, 112, 'وَبَشَّرْنَاهُ بِإِسْحَاقَ نَبِيًّا مِنَ الصَّالِحِينَ', 0),
(3901, 37, 113, 'وَبَارَكْنَا عَلَيْهِ وَعَلَىٰ إِسْحَاقَ ۚ وَمِنْ ذُرِّيَّتِهِمَا مُحْسِنٌ وَظَالِمٌ لِنَفْسِهِ مُبِينٌ', 0),
(3902, 37, 114, 'وَلَقَدْ مَنَنَّا عَلَىٰ مُوسَىٰ وَهَارُونَ', 0),
(3903, 37, 115, 'وَنَجَّيْنَاهُمَا وَقَوْمَهُمَا مِنَ الْكَرْبِ الْعَظِيمِ', 0),
(3904, 37, 116, 'وَنَصَرْنَاهُمْ فَكَانُوا هُمُ الْغَالِبِينَ', 0),
(3905, 37, 117, 'وَآتَيْنَاهُمَا الْكِتَابَ الْمُسْتَبِينَ', 0),
(3906, 37, 118, 'وَهَدَيْنَاهُمَا الصِّرَاطَ الْمُسْتَقِيمَ', 0),
(3907, 37, 119, 'وَتَرَكْنَا عَلَيْهِمَا فِي الْآخِرِينَ', 0),
(3908, 37, 120, 'سَلَامٌ عَلَىٰ مُوسَىٰ وَهَارُونَ', 0),
(3909, 37, 121, 'إِنَّا كَذَٰلِكَ نَجْزِي الْمُحْسِنِينَ', 0),
(3910, 37, 122, 'إِنَّهُمَا مِنْ عِبَادِنَا الْمُؤْمِنِينَ', 0),
(3911, 37, 123, 'وَإِنَّ إِلْيَاسَ لَمِنَ الْمُرْسَلِينَ', 0),
